import{z as i,x as s,o as e,c as d,q as n,j as r,D as E,d as o,s as A,S as l,b as B}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"理性泡沫","description":"","frontmatter":{"title":"理性泡沫","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/rational-bubbles.md","filePath":"econ/rational-bubbles.md","lastUpdated":1791413859000}'),p={name:"econ/rational-bubbles.md"};function m(c,a,_,h,u,D){const t=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=n('<h1 id="理性泡沫" tabindex="-1">理性泡沫 <a class="header-anchor" href="#理性泡沫" aria-label="Permalink to &quot;理性泡沫&quot;">​</a></h1><div class="epigraph"><p>价格可以等于基本面加上一项爆炸的期望项；每个人都知道它是泡沫，只要能在破裂前卖给下一个人，持有仍然理性。</p><footer>—— Blanchard and Watson, 1982；Tirole, Asset Bubbles and Overlapping Generations, Econometrica 1985；Santos and Woodford, Econometrica 1997</footer></div><p><a href="/econ/scheinkman-xiong">上一课</a>的泡沫靠分歧。本课缺口是共同信念：欧拉 \\(p_t=E_t[m_{t+1}(p_{t+1}+d_{t+1})]\\) 的解可以含泡沫项 \\(B_t\\)，只要 \\(B_t=E_t[m_{t+1}B_{t+1}]\\)。不重写转售期权，不重推 <a href="/econ/stochastic-discount-factor">SDF</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无泡沫解把价格写成贴现股息的和。齐次方程允许 \\(B_t\\)，期望按 \\(1/m\\) 增长。Blanchard 与 Watson 的随机泡沫以正概率破裂。Tirole（1985）在 OLG 里给出存在条件：泡沫可以在动态无效率经济里改善配置，吸收过度储蓄。Santos 与 Woodford（1997）在有限代理人、有限资源下给出否定性结果：许多标准经济里泡沫无法存在。缺口是标明「理性、共同信念」这一支，对照行为泡沫，而不是重讲欧拉。</p><p><span class="marginnote">术语翻译：「齐次解」是说欧拉方程只钉住价格「怎么随未来变」，对「起点多高」留了一个自由度；横截条件把这个自由度拧死为 0，没有横截（如 OLG）时，就可以填进一个自我实现的数——那就是 \\(B\\)。</span></p><p><span class="marginnote">横截条件 \\(\\lim E[m_{0,T}p_T]=0\\) 关掉泡沫。无限期代表主体加非蓬齐通常施加这一条。OLG 没有代表主体的横截，门缝打开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从资产欧拉分解 \\(p=p^*+B\\)。讨论何时 \\(B\\equiv 0\\) 是唯一解：正净供给的资产在有效经济、债务约束、横截。何时可正：OLG 无效率、某些不完全市场。破裂风险把泡沫收益率抬高，补偿爆破。本课不估计哪一次历史是 \\(B\\)。</p>',9)),(e(),r(l,null,{default:E(()=>[A(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20EUL%5B%22%E6%AC%A7%E6%8B%89%E5%88%86%E8%A7%A3%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20STAR%5B%22%E5%9F%BA%E6%9C%AC%E9%9D%A2%20p-star%22%5D%0A%20%20EUL%20--%3E%20B%5B%22%E6%B3%A1%E6%B2%AB%E9%A1%B9%E9%9A%8F%E6%A0%B8%E5%A2%9E%E9%95%BF%22%5D%0A%20%20B%20--%3E%20OLG%5B%22OLG%20%E6%97%A0%E6%95%88%E7%8E%87%3A%20%E5%8F%AF%E4%BB%A5%E5%AD%98%E5%9C%A8%22%5D%0A%20%20B%20--%3E%20SW%5B%22%E6%9C%89%E9%99%90%E8%B5%84%E6%BA%90%E5%8A%A0%E6%A8%AA%E6%88%AA%3A%20%E5%B8%B8%E5%B8%B8%E4%B8%8D%E8%83%BD%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[o("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"机制是自我实现的期望。人愿意付 \\(B\\) 是因为别人明天愿意付 \\(B/m\\) 的期望。没有人被骗，也没有过度自信。换手不是必需品——与 SX 对照。配置上，泡沫作为金字塔资产与实物资本竞争：Tirole 的福利含义依赖经济是否已经过度积累。这与宏观 OLG 课衔接，不重写 Diamond 模型。",-1)),(e(),r(l,null,{default:E(()=>[A(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20PAY%5B%22%E4%BB%8A%E5%A4%A9%E4%BB%98%20B%3A%20%E9%AB%98%E4%BA%8E%E5%9F%BA%E6%9C%AC%E9%9D%A2%22%5D%20--%3E%20BELIEF%5B%22%E9%A2%84%E6%9C%9F%E5%88%AB%E4%BA%BA%E6%98%8E%E5%A4%A9%E6%84%BF%E4%BB%98%20B%20%E7%9A%84%E6%9C%9F%E6%9C%9B%E5%80%BC%22%5D%0A%20%20BELIEF%20--%3E%20RESALE%5B%22%E5%9C%A8%E7%A0%B4%E8%A3%82%E5%89%8D%E5%8D%96%E5%87%BA%E4%BB%8D%E7%84%B6%E5%88%92%E7%AE%97%22%5D%0A%20%20RESALE%20--%3E%20CHAIN%5B%22%E4%B8%8B%E4%B8%80%E4%B8%AA%E4%BA%BA%E5%81%9A%E5%90%8C%E6%A0%B7%E7%9A%84%E6%8E%A8%E7%90%86%22%5D%0A%20%20CHAIN%20--%3E%20BELIEF%0A%20%20CHAIN%20--%3E%20CRASH%5B%22%E4%BB%A5%E6%AD%A3%E6%A6%82%E7%8E%87%E7%A0%B4%E8%A3%82%E5%BD%92%E9%9B%B6%22%5D%0A%20%20CRASH%20--%3E%20YIELD%5B%22%E6%8C%81%E6%9C%89%E8%80%85%E8%A6%81%E6%B1%82%E6%9B%B4%E9%AB%98%E7%9A%84%E6%9C%9F%E6%9C%9B%E6%B6%A8%E5%B9%85%E4%BD%9C%E8%A1%A5%E5%81%BF%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p>与套利限制：理性泡沫要求有人愿意在破裂风险下持有 \\(B\\)。无限资本的套利者若能卖空泡沫资产，会压 \\(B\\)。存在性因此对卖空与入场极敏感——Abreu–Brunnermeier 下一课把「何时卖空」变成同步问题。</p><p>横截条件把代表主体经济里的 \\(B\\) 关掉；OLG 没有这条横截，动态无效率时泡沫可改善配置。Santos–Woodford 提醒：有限资源加债务约束，许多看起来能存在的 \\(B\\) 其实不能。可检验性弱于 SX：理性泡沫不承诺高换手。本课不把「价格高」命名为 \\(B\\)。欧拉分解不重推 SDF，只引用已有核。</p><p><span class="marginnote">数字实例：取 \\(m=1/(1+r)\\)、\\(r=5\\%\\)：泡沫项每年要按约 5% 的期望速度膨胀才够本——今天 100 元的 \\(B\\)，明年平均要值 105 元。若每年另有 10% 概率破裂归零，持有者还会要求更高的期望涨幅作风险补偿。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>可检验性弱：任何价格路径都可以被写成某种 \\(B\\) 加上某种 \\(p^*\\)。本课不把「价格高」叫成理性泡沫。行为泡沫给出换手、分歧、盈余路径等额外符号，识别更富。也不把比特币写进正文。</p><p><span class="marginnote">常见误区：初学者容易以为泡沫里全是傻子。理性泡沫恰恰假设没有傻子——人人都知道价格高出基本面，只要「破裂前能卖给下一个人」的信念不断裂，继续持有就是理性选择。</span></p><p>后课默认：即使人人知道价格太高，同步失败仍能让泡沫继续——那是攻击时机，不是欧拉齐次项。</p><p>欧拉齐次项 \\(B\\) 在共同信念下仍可能；人愿意付 \\(B\\) 是因为别人明天愿意付。</p><p>横截关掉代表主体经济里的泡沫；OLG 无效率打开门。可检验性弱于换手–分歧故事。</p><p><span class="marginnote">可检验性弱于换手–分歧故事；存在性对卖空与横截极敏感。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>理性泡沫是欧拉齐次解，共同信念下仍可能。</li><li>Tirole：OLG 无效率打开存在之门；Santos–Woodford 收紧。</li><li>与 SX 对照：不需要分歧与换手，但可检验性更弱。</li><li>破裂风险要求更高的持有收益。</li><li>「价格高」不能直接命名为 \\(B\\)。</li><li>出处：Blanchard and Watson 1982；Tirole, <em>Econometrica</em> 1985；Santos and Woodford, <em>Econometrica</em> 1997。</li></ul>',12))])}const b=i(p,[["render",m]]);export{C as __pageData,b as default};
